#!/usr/bin/env python3
"""Original finite-domain content constructions for Milestone 3 research.
No network calls, external problem scripts, or unrestricted expression parsing.
Mathematical verification is separate from editorial difficulty admission.
"""
import argparse, hashlib, json, math, sys, re
from pathlib import Path
import sympy as s
x,y,t,z=s.symbols('x y t z', real=True)
k=s.symbols('k',integer=True,positive=True)
R=s.Rational
FAMILIES=[]

def latex(v):return s.latex(s.sympify(v),fold_short_frac=False)
def text(v):
 escapes={'\\':r'\textbackslash{}','{':r'\{','}':r'\}','^':r'\textasciicircum{}','_':r'\_','&':r'\&','%':r'\%','$':r'\$','#':r'\#','~':r'\textasciitilde{}'}
 return r'\textnormal{'+''.join(escapes.get(c,c) for c in v)+'}'
def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def equal(a,b):
 d=s.simplify(s.expand_func(a-b))
 return d.is_zero_matrix is True if isinstance(d,s.MatrixBase) else d==0

def register(topic,level,slug,group,method,demand,why,build,*,alternatives=(),prerequisites=(),fit='candidate'):
 FAMILIES.append(dict(topic=topic,difficulty=level,familyId='m3-'+topic.replace(' ','-')+'-'+level+'-'+slug,relatedIdeaGroupId=group,primaryTechnique=method,alternativeTechniques=list(alternatives),reasoningDemand=demand,difficultyRationale=why,build=build,prerequisites=list(prerequisites),editorialStatus=fit))

def proof(statement,answer,wrongs,steps,checks,domain,route,structure):
 a=s.sympify(answer)
 assert checks and all(c is True or c is s.true for c in checks), 'certificate did not close'
 assert not a.has(s.Integral,s.Sum,s.Limit,s.nan,s.zoo,s.oo,-s.oo)
 assert a.is_real is not False
 options=[(a,'correct')]
 for w,why in wrongs:
  w=s.sympify(w)
  if w.has(s.nan,s.zoo,s.oo,-s.oo) or w.is_real is False:continue
  if all(not equal(w,v) for v,_ in options):options.append((w,why))
 assert len(options)>=4, 'need three inequivalent authored distractors'
 return dict(automatedChecks=[{'checkIndex':i,'passed':True,'scope':'exact constructor assertion; see trusted build source'} for i in range(len(checks))],statement=statement,answer=a,options=options,solutionSteps=steps+[latex(a)],domain=domain,verificationRoute=route,structuralSignature=structure)

def derivative(expr,point,answer,wrongs,idea,order=1,structure='explicit-derivative'):
 derivative=s.diff(expr,x,order); actual=s.simplify(derivative.subs(x,point))
 wrongs=list(wrongs)+[(expr.subs(x,point),'return the function value instead of the requested derivative'),(s.diff(expr,x,max(0,order-1)).subs(x,point),'differentiate one fewer time'),(s.diff(expr,x,order+1).subs(x,point),'differentiate one additional time')]
 return proof(r'\left.\frac{d^{'+str(order)+r'}}{dx^{'+str(order)+r'}}\left('+latex(expr)+r'\right)\right|_{x='+latex(point)+'}',answer,wrongs,[text(idea),r'f^{('+str(order)+')}(x)='+latex(derivative),text('Evaluate at the specified point.')],[equal(actual,answer)],['Real x in a neighborhood of '+str(point)+'.'],'exact-symbolic-differentiation',structure)

def integral(expr,F,lo,hi,answer,wrongs,idea,domain=(),structure='definite-integral'):
 lower=s.limit(F,x,lo,dir='+') if lo in (0,-s.oo) else F.subs(x,lo)
 upper=s.limit(F,x,hi,dir='-') if hi in (s.oo,) else F.subs(x,hi)
 wrongs=list(wrongs)+[(upper,'omit the lower endpoint contribution'),(-lower,'omit the upper endpoint contribution'),(upper+lower,'add the endpoint values instead of subtracting'),(lower-upper,'reverse the endpoint order')]
 return proof(r'\int_{'+latex(lo)+'}^{'+latex(hi)+'}'+latex(expr)+r'\,dx',answer,wrongs,[text(idea),r'F(x)='+latex(F),r'F(b)-F(a)='+latex(upper)+'-('+latex(lower)+')'],[equal(s.diff(F,x),expr),equal(upper-lower,answer)],list(domain)+['The displayed antiderivative is differentiable throughout the interval interior; finite one-sided limits are used at improper endpoints.'],'antiderivative-and-endpoint-certificate',structure)

def limit(expr,point,answer,wrongs,idea,structure='one-variable-limit',direction='+'):
 actual=s.limit(expr,x,point,dir=direction)
 wrongs=list(wrongs)+([(s.Integer(0),'discard the first surviving limit term'),(-answer,'reverse the sign of the surviving term'),(1/s.sympify(answer),'take the reciprocal of the final ratio')] if answer!=0 else [])
 return proof(r'\lim_{x\to '+latex(point)+(r'^+' if point!=s.oo and direction=='+' else '')+'}'+latex(expr),answer,wrongs,[text(idea),latex(s.Eq(s.Limit(expr,x,point,dir=direction),answer,evaluate=False))],[equal(actual,answer)],['Approach through the real domain; the indicated one-sided limit is used.'],'exact-symbolic-limit',structure)

def algebra(statement,answer,wrongs,steps,lhs,rhs,domain=(),structure='algebraic-certificate',route='exact-algebraic-certificate'):
 return proof(statement,answer,wrongs,steps,[equal(lhs,rhs)],list(domain),route,structure)

def select_options(pool,m):
 """Choose only authored, exactly inequivalent errors; balance numeric rank where feasible.
 Numerical ordering is a presentation diagnostic, never a correctness proof.
 """
 answer=pool[0];wrongs=pool[1:]
 try:
  av=float(s.N(answer[0],40))
  low=[o for o in wrongs if float(s.N(o[0],40))<av]
  high=[o for o in wrongs if float(s.N(o[0],40))>av]
  feasible=[r for r in range(1,5) if len(low)>=r-1 and len(high)>=4-r]
  if not feasible:raise ValueError('numeric ordering unresolved')
  desired=feasible[(m-4)%len(feasible)]
  low=low[(m-4)%len(low):]+low[:(m-4)%len(low)] if low else []
  high=high[(m-4)%len(high):]+high[:(m-4)%len(high)] if high else []
  selected=low[:desired-1]+high[:4-desired]
  return [answer]+selected,{'authoredWrongOptionCount':len(wrongs),'feasibleCorrectNumericRanks':feasible,'correctNumericRank':desired,'numericalOrderingUsedAsProof':False,'fixedNumericRankRisk':len(feasible)==1}
 except (TypeError,ValueError,OverflowError):
  selected=(wrongs[(m-4)%len(wrongs):]+wrongs[:(m-4)%len(wrongs)])[:3]
  return [answer]+selected,{'authoredWrongOptionCount':len(wrongs),'feasibleCorrectNumericRanks':[],'correctNumericRank':None,'numericalOrderingUsedAsProof':False,'fixedNumericRankRisk':None}

def materialize(f,m):
 p=f['build'](s.Integer(m)); a=p.pop('answer'); pool=p.pop('options')
 opts,option_audit=select_options(pool,m)
 if re.search(r'(?<![A-Za-z])m(?![A-Za-z])',p['statement']):p['statement']=text('Set ')+r'm='+str(m)+r'.\quad '+p['statement']
 p['solutionSteps']=[text('Here ')+r'm='+str(m)+'.']+p['solutionSteps']
 identity={'familyId':f['familyId'],'parameter':m,'statement':p['statement']}
 semantic=digest(identity); choices=[{'choiceId':'ch_'+digest(s.srepr(v))[:16],'math':latex(v),'misconception':why} for v,why in opts]
 record={k:v for k,v in f.items() if k!='build'}
 record.update(p,problemId='cn_m3_'+semantic[:20],problemRevision=1,parameters={'m':m},parameterDomain={'m':list(range(4,12))},choices=choices,answerChoiceId=choices[0]['choiceId'],answerForm='exact-expression',schemaVersion=2,semanticHash=semantic,normalizedStructure=p['structuralSignature'],source={'kind':'independently-authored','thirdPartyProblemAdapted':False,'attribution':'Original Calculus Ninja content, AI-assisted; exact verification recorded separately.','license':'LicenseRef-CalculusNinja-Original'},validation={'status':'candidate-automated-checks-passed','route':p['verificationRoute'],'engine':'SymPy '+s.__version__,'humanReviewed':False,'editorialReview':'AI-assisted; not human review','numericalAgreementUsedAsProof':False,'parameterCheck':m in range(4,12),'uniqueCorrectOption':True},estimatedSolveSeconds={'easy':50,'medium':110,'hard':220,'olympiad':420}[f['difficulty']])
 record['validation']['editorialStatus']=f['editorialStatus']
 record['validation']['status']='verified' if f['editorialStatus']=='admitted' else ('quarantined' if f['editorialStatus']=='quarantined' else 'candidate-automated-checks-passed')
 record['validation']['automatedChecks']=p.get('automatedChecks',[])
 record['validation']['distractorAudit']=option_audit
 record['answerForm']=p.get('answerForm','exact-expression')
 record['pedagogy']={'constructionId':f['familyId'],'relatedIdeaGroupId':f['relatedIdeaGroupId'],'structuralSignature':p['structuralSignature'],'primaryTechnique':f['primaryTechnique'],'alternativeTechniques':f['alternativeTechniques'],'prerequisites':f['prerequisites'],'reasoningDemand':[f['reasoningDemand']],'answerForm':record['answerForm'],'difficultyRationale':f['difficultyRationale'],'sourceRecordIds':[],'responseFormat':'multiple-choice'}
 record['contentHash']=digest(record)
 return record

# Integration: each family is one decision/structure, not a sum of fixed kernels.
def integration_cases():
 for level in ['easy','medium','hard']:
  L={'easy':0,'medium':1,'hard':2}[level]
  def add(slug,group,method,build,why):register('integration',level,slug,group,method,'execution' if L==0 else 'method-selection',why,build,fit='reviewed-candidate')
  if L==0:
   add('signed-area','signed-versus-geometric-area','split-at-zero',lambda m:integral(x-m,x*x/2-m*x,0,2*m,0,[(m*m,'count both lobes positively'),(-m*m,'retain only negative lobe'),(m*m/2,'triangle-width error')],'The positive and negative triangular areas cancel.',structure='affine-sign-change-symmetric-bounds'),'Distinguishes signed accumulation from total geometric area.')
   add('absolute-area','absolute-value-integration','split-at-zero',lambda m:algebra(r'\int_0^{'+latex(2*m)+'}|x-'+latex(m)+r'|\,dx',m*m,[(0,'omit absolute value'),(2*m*m,'use rectangles instead of triangles'),(m*m/2,'count only one lobe')],[text('Split at x=m. Each triangle has area m squared over two.')],s.integrate(m-x,(x,0,m))+s.integrate(x-m,(x,m,2*m)),m*m,structure='absolute-linear-integrand'),'Requires splitting at a cusp rather than applying a power rule.')
   add('substitution-affine','substitution-jacobian','substitution',lambda m:integral((m*x+1)**2,(m*x+1)**3/(3*m),0,1,((m+1)**3-1)/(3*m),[(((m+1)**3-1)/3,'omit Jacobian'),((m+1)**3/(3*m),'omit lower limit'),(((m+1)**3-1)/(2*m),'wrong power denominator')],'Set u=mx+1 and include dx=du/m.',structure='affine-composition-power'),'A single substitution with changed endpoints.')
   add('log-recognition','logarithmic-antiderivative','recognition',lambda m:integral(1/(x+m),s.log(x+m),0,1,s.log((m+1)/m),[(s.log(m+1),'omit lower endpoint'),(s.log(m/(m+1)),'reverse endpoints'),(s.log((m+2)/m),'shift upper endpoint')],'The integrand is the logarithmic derivative of x+m.',domain=['x+m>0.'],structure='reciprocal-affine'),'Recognizes the logarithmic exceptional power.')
   add('exponential-rate','exponential-substitution','recognition',lambda m:integral(s.exp(m*x),s.exp(m*x)/m,0,1,(s.exp(m)-1)/m,[(s.exp(m)-1,'omit inner derivative'),(s.exp(m)/m,'omit lower endpoint'),((s.exp(m)-1)/m**2,'divide twice')],'Divide the exponential by its inner derivative.',structure='exponential-linear-inner'),'One inner derivative, with a nonzero lower endpoint.')
   add('quarter-disk','geometric-integral','geometry',lambda m:algebra(r'\int_0^{'+latex(m)+r'}\sqrt{'+latex(m*m)+r'-x^2}\,dx',s.pi*m*m/4,[(s.pi*m*m/2,'use a semicircle'),(s.pi*m*m,'use a full disk'),(s.pi*m/4,'confuse radius and squared radius')],[text('The graph is the upper semicircle of radius m; this interval covers one quarter of its disk.')],s.pi*m*m/4,s.pi*m*m/4,domain=['m>0; principal nonnegative square root.'],structure='quarter-circle-area',route='Euclidean-area-certificate'),'Uses geometry without an antiderivative.')
   add('average-value','integral-average','normalization',lambda m:algebra(text('Find the average of ')+r'f(x)=x^2'+text(' on ')+r'[0,'+latex(m)+']',m*m/3,[(m**3/3,'forget to divide by interval length'),(m*m/2,'average endpoint values'),(m*m,'take the endpoint maximum')],[text('Average value is the integral divided by interval length.'),r'\frac1{'+latex(m)+r'}\int_0^{'+latex(m)+r'}x^2\,dx='+latex(m*m/3)],s.integrate(x*x,(x,0,m))/m,m*m/3,structure='mean-value-normalized-integral'),'Separates average value from total accumulation.')
   add('odd-even','parity-on-symmetric-domain','symmetry',lambda m:integral(x**3+s.cos(x),x**4/4+s.sin(x),-s.pi/m,s.pi/m,2*s.sin(s.pi/m),[(0,'discard both terms as odd'),(s.sin(s.pi/m),'keep only half interval'),(2*s.sin(s.pi/m)+s.pi**4/(2*m**4),'treat odd term as positive')],'The cubic integrates to zero on symmetric bounds; cosine is even.',structure='mixed-parity-symmetric-bounds'),'Uses parity before computation.')
   add('accumulation-from-derivative','fundamental-theorem','FTC',lambda m:algebra(text('If ')+r'F(1)='+latex(m)+r',\quad F(3)='+latex(m*m+1)+text(', find ')+r'\int_1^3 F\prime(x)\,dx',m*m+1-m,[(m*m+1+m,'add endpoint values'),(m*m+1,'omit lower endpoint'),((m*m+1-m)/2,'return average derivative')],[text('The Fundamental Theorem gives F(3)-F(1).')],(m*m+1)-m,m*m+1-m,domain=['F is continuously differentiable on [1,3].'],structure='endpoint-data-FTC'),'Interprets supplied function values, not an explicit formula.')
   add('piecewise-accumulation','piecewise-integration','interval-split',lambda m:algebra(r'\int_0^2 f(x)\,dx,\qquad f(x)=\begin{cases}'+latex(m)+r'x,&0\le x\le1,\\'+latex(m+1)+r',&1<x\le2.\end{cases}',R(3,2)*m+1,[(2*m+1,'treat first interval as rectangle'),(m+1,'ignore first interval'),(R(3,2)*m+R(1,2),'treat second interval as triangle')],[text('Integrate each formula only on its own interval.'),latex(m/2)+'+'+latex(m+1)],s.integrate(m*x,(x,0,1))+s.integrate(m+1,(x,1,2)),R(3,2)*m+1,structure='piecewise-affine-constant'),'Requires interval bookkeeping at a formula change.')
   add('area-between-curves','area-as-difference','geometry',lambda m:integral(m*x-x*x,m*x*x/2-x**3/3,0,m,m**3/6,[(m**3/3,'integrate lower curve only'),(m**3/2,'integrate upper curve only'),(-m**3/6,'reverse upper and lower')],'The curves meet at 0 and m; mx lies above x squared between them.',structure='parabola-line-enclosed-area'),'Finds intersections and subtracts the lower graph.')
