  if L==1:
   add('parts-log','logarithm-integration-by-parts','integration-by-parts',lambda m:integral(s.log(x),x*s.log(x)-x,1,m,m*s.log(m)-m+1,[(m*s.log(m)-m,'omit lower contribution'),(m*s.log(m)+m-1,'wrong parts sign'),(s.log(m)**2/2,'treat log as reciprocal')],'Take u=log x and dv=dx.',domain=['x>=1.'],structure='logarithm-parts'),'Chooses parts because substitution does not remove the logarithm.')
