   add('rational-power-substitution','derivative-over-denominator','substitution',lambda m:integral(2*x/(1+x*x)**m,(1+x*x)**(1-m)/(1-m),0,1,(1-2**(1-m))/(m-1),[((1-2**(1-m))/m,'wrong new exponent'),((2**(1-m)-1)/(m-1),'sign reversal'),(1/(m-1),'drop finite upper contribution')],'Set u=1+x squared; the numerator is exactly du.',structure='quadratic-denominator-derivative-match'),'Recognizes an inner derivative and manages a negative power.')
   add('trig-odd-power','trigonometric-power-substitution','trig-substitution',lambda m:integral(s.sin(x)*s.cos(x)**m,-s.cos(x)**(m+1)/(m+1),0,s.pi/2,1/(m+1),[(1/m,'miss increment in exponent'),(1/(m+2),'increment twice'),(2/(m+1),'double a half-period')],'Use u=cos x; its derivative contributes the minus sign.',structure='odd-sine-even-or-odd-cosine-power'),'A saved odd factor supplies the substitution.')
   add('secant-square-substitution','trigonometric-composition','substitution',lambda m:integral(s.tan(x)**m/s.cos(x)**2,s.tan(x)**(m+1)/(m+1),0,s.pi/4,1/(m+1),[(1/m,'wrong power denominator'),(s.pi/(4*(m+1)),'retain old endpoint'),(2/(m+1),'spurious double-angle factor')],'Set u=tan x and change the endpoint to one.',structure='tan-power-with-sec-squared'),'Requires recognizing a derivative hidden by reciprocal cosine.')
