  if L==2:
   add('logarithmic-moment','endpoint-log-moment','repeated-parts',lambda m:algebra(r'\int_0^1 x^{'+latex(m)+r'}(\log x)^2\,dx',2/(m+1)**3,[(1/(m+1)**2,'differentiate parameter only once'),(2/m**3,'wrong shifted exponent'),(-2/(m+1)**3,'wrong logarithm sign')],[text('Differentiate the convergent identity integral x^a=1/(a+1) twice in a; domination holds near a=m> -1.')],s.diff(1/(x+1),x,2).subs(x,m),2/(m+1)**3,domain=['m>=2; x^m log(x)^2 is integrable at zero.'],structure='log-squared-endpoint-moment',route='dominated-parameter-differentiation-certificate'),'A logarithmic endpoint requires justification before parameter differentiation.')
   add('beta-polynomial','beta-integral','beta-reduction',lambda m:algebra(r'\int_0^1 x^{'+latex(m)+r'}(1-x)^{'+latex(m+1)+r'}\,dx',s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+2),[(s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+1),'wrong total Gamma index'),(s.factorial(m+1)**2/s.factorial(2*m+2),'raise one exponent'),(s.factorial(m)**2/s.factorial(2*m+2),'drop one factorial')],[text('Repeated integration by parts gives the beta factorial identity; all endpoint terms vanish.')],s.integrate(s.expand(x**m*(1-x)**(m+1)),(x,0,1)),s.factorial(m)*s.factorial(m+1)/s.factorial(2*m+2),domain=['Nonnegative integer exponents.'],structure='beta-polynomial-two-endpoints'),'Uses a recurrence or beta structure instead of expanding a long polynomial.')
