 def d(expr,p,A,W,idea,order=1,structure='explicit'):
  return derivative(expr,p,A,[(v,['omit a derivative contribution','misapply the chain or product rule','use the wrong derivative order','evaluate at the wrong point'][i%4]) for i,v in enumerate(W)],idea,order,structure)
