def lagrange_example(n):
 # y=x(1+y)^2: Catalan generating function, direct coefficient recursion is independent of the closed formula.
 coeff=[s.Integer(0)]*(n+1)
 for j in range(1,n+1):coeff[j]=1 if j==1 else 2*coeff[j-1]+sum(coeff[a]*coeff[j-1-a] for a in range(1,j-1))
 A=s.factorial(n)*s.binomial(2*n,n)/(n+1)
 return algebra(r'y=x(1+y)^2,\ y(0)=0,\ y\textnormal{ analytic. Find }y^{('+str(n)+r')}(0).',A,[(s.binomial(2*n,n)/(n+1),'return coefficient not derivative'),(s.factorial(n)*s.binomial(2*n,n),'omit Catalan normalization'),(s.factorial(n)*s.binomial(2*n-1,n)/(n+1),'wrong inversion coefficient')],[text('The implicit function theorem gives a unique analytic branch. Lagrange inversion gives [x^n]y=(1/n)[u^(n-1)](1+u)^(2n).'),text('Multiply the coefficient by n factorial.')],s.factorial(n)*coeff[n],A,domain=['Analytic branch at x=0 with y=0.'],structure='implicit-quadratic-series-inversion',route='finite-coefficient-recursion-versus-Lagrange-certificate')
def mobius_example(n):
 M=s.Matrix([[1,1],[1,2]])**n;a,b,c,d=M[0,0],M[0,1],M[1,0],M[1,1]
 expr=x
 for _ in range(n):expr=s.cancel((expr+1)/(expr+2))
 A=1/d**2
 return algebra(r'f(x)=\frac{x+1}{x+2}.\quad (f^{\circ '+str(n)+r'})\prime(0)=?',A,[(1/d,'omit squared denominator'),(1/c**2,'use wrong matrix entry'),(1/(c+d)**2,'evaluate at one instead of zero')],[text('Composition corresponds to multiplying the matrix [[1,1],[1,2]], whose determinant is one.'),r'M^n='+s.latex(M),text('For (ax+b)/(cx+d), the derivative at zero is det(M)/d squared.')],s.diff(expr,x).subs(x,0),A,domain=['All denominators stay positive near zero.'],structure='Mobius-iterate-derivative',route='symbolic-composition-versus-matrix-certificate')
def exp_partition_example(n):
 A=s.factorial(n)*sum(s.binomial(n-1,j-1)/s.factorial(j) for j in range(1,n+1))
 return derivative(s.exp(x/(1-x)),0,A,[(A/s.factorial(n),'forget coefficient-to-derivative factor'),(s.factorial(n)*2**(n-1),'forget j factorial weights'),(s.factorial(n)*sum(s.binomial(n,j)/s.factorial(j) for j in range(1,n+1)),'wrong binomial index')],'Expand exp(x/(1-x)) as a sum over j. The x^n coefficient of x^j(1-x)^-j is binomial(n-1,j-1).',order=n,structure='exp-of-geometric-generating-function')
def interpolation_example(n):
 points=[(j,R(1,j+1)) for j in range(n+1)]
 P=s.interpolate(points,x)
 # (x+1)P(x)-1 has known roots 0..n; evaluate at -1 to determine C.
 C=(-1)**n/s.factorial(n+1)
 Q=C*s.prod(x-j for j in range(n+1))
 A=s.diff(Q,x).subs(x,0)-1
 return algebra(text('P is the polynomial of degree at most ')+str(n)+text(' with ')+r'P(j)=\frac1{j+1},\quad j=0,\ldots,'+str(n)+r'.\quad P\prime(0)=?',A,[(A+1,'omit differentiating the x+1 factor'),(-A,'reverse interpolation error sign'),(-1,'differentiate sampled rational function instead of interpolant')],[text('R(x)=(x+1)P(x)-1 vanishes at all interpolation nodes. Thus R=C product(x-j), with C fixed by R(-1)=-1.'),text('Differentiate at zero: P(0)+P prime(0)=R prime(0).')],s.diff(P,x).subs(x,0),A,structure='rational-samples-polynomial-interpolant',route='exact-interpolation-versus-error-polynomial-certificate')

