def catalog():
 return [{k:v for k,v in f.items() if k!='build'}|{'instanceIndices':list(range(8))} for f in FAMILIES]
def build(family_id, instance_index):
 if type(instance_index) is not int or not 0<=instance_index<8:raise ValueError('instance index outside finite verified domain')
 family=next((f for f in FAMILIES if f['familyId']==family_id),None)
 if family is None:raise ValueError('unknown original construction')
 return materialize(family,instance_index+4)
def all_candidates():
 for f in FAMILIES:
  for i in range(8):yield build(f['familyId'],i)

