def series_problem(term,start,A,W,idea,shape,convergence,check=None,route='exact-symbolic-summation'):
 actual=s.summation(term,(k,start,s.oo)) if check is None else check
 first=term.subs(k,start)
 W=list(W)+[A-first,A+first,first]
 return proof(r'\sum_{k='+str(start)+r'}^\infty '+latex(term),A,[(v,why) for v,why in zip(W,['wrong starting index or omitted endpoint','wrong differentiation or integration factor','wrong convergence/normalization factor','omit the first included term','include the first term twice','return only the first term'])],[text(idea),text(convergence)],[equal(actual,A)],[convergence],route,shape)
def finite_series(term,lo,hi,A,W,idea,shape):
 actual=s.summation(term,(k,lo,hi))
 first=term.subs(k,lo);last=term.subs(k,hi)
 W=list(W)+[A-first,A-last,A+last]
 return proof(r'\sum_{k='+str(lo)+'}^{'+latex(hi)+'}'+latex(term),A,[(v,why) for v,why in zip(W,['endpoint count error','wrong index shift','wrong summation identity','omit the first summand','omit the last summand','include the last summand twice'])],[text(idea)],[equal(actual,A)],['Finite sum with integer endpoints.'],'exact-finite-summation',shape)
def class_series(statement,correct,alternatives,steps,checks,domain,shape):
 assert len(set([correct]+alternatives))==4
 assert checks and all(c is True or c is s.true for c in checks)
 # Text classes remain private scalar options, never correctness heuristics from length.
 return {'statement':statement,'answer':s.Integer(0),'options':[(s.Symbol(correct), 'correct')]+[(s.Symbol(v),'misclassification') for v in alternatives], 'solutionSteps':[text(v) for v in steps],'domain':domain,'verificationRoute':'convergence-theorem-with-explicit-hypotheses','structuralSignature':shape}

